def naive_plan(rows):
    """Groups first, then filters -- extra work on rows that get discarded."""
    groups = {}
    for r in rows:
        groups.setdefault(r["dept"], []).append(r)
    filtered = {}
    scanned = 0
    for dept, members in groups.items():
        kept = [m for m in members if m["salary"] > 50000]
        scanned += len(members)
        if kept:
            filtered[dept] = len(kept)
    return filtered, scanned

def pushdown_plan(rows):
    """Catalyst-style plan: filter before grouping, so fewer rows reach the
    aggregation step."""
    scanned = 0
    filtered_rows = []
    for r in rows:
        scanned += 1
        if r["salary"] > 50000:
            filtered_rows.append(r)
    groups = {}
    for r in filtered_rows:
        groups[r["dept"]] = groups.get(r["dept"], 0) + 1
    return groups, len(filtered_rows)

users = [
    {"dept": "eng", "salary": 60000},
    {"dept": "eng", "salary": 40000},
    {"dept": "sales", "salary": 55000},
    {"dept": "sales", "salary": 30000},
]

naive_result, naive_scanned = naive_plan(users)
push_result, push_rows_after_filter = pushdown_plan(users)
print("naive result:", naive_result)
print("pushdown result:", push_result)
print("rows after filter (pushdown):", push_rows_after_filter, "of", len(users))

